/**
 * Embeds the EpiCare web app (../app) into the native app as one self-contained HTML page.
 *
 *   node scripts/build-web.js        (also run automatically by `npm start`)
 *
 * Inlines styles.css, app.js, the results JSON (app/data/app_data.json, plus branch2.json if
 * present) and the header icon, so the native app works offline and needs no web server.
 * Output: web/epicare-html.js (generated, do not edit).
 */
const fs = require("fs");
const path = require("path");

const APP = path.resolve(__dirname, "..", "..", "app");
const OUT = path.resolve(__dirname, "..", "web", "epicare-html.js");

const read = (f) => fs.readFileSync(path.join(APP, f), "utf8");
const readJson = (f) => {
  const p = path.join(APP, f);
  return fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : null;
};
// "</script>" inside inlined code or data would close the tag early
const safe = (s) => s.replace(/<\/script/gi, "<\\/script");

let html = read("index.html");
const css = read("styles.css");
const js = read("app.js");
const data = readJson("data/app_data.json");
const branch2 = readJson("data/branch2.json");
const icon = "data:image/png;base64," + fs.readFileSync(path.join(APP, "icons", "icon-192.png")).toString("base64");

html = html
  .replace(/<link rel="(manifest|apple-touch-icon|icon)"[^>]*>\s*/g, "")
  .replace('<link rel="stylesheet" href="styles.css">', () => `<style>${css}</style>`)
  .replace('src="icons/icon-192.png"', () => `src="${icon}"`)
  .replace('<script src="app.js"></script>', () =>
    `<script>window.EPICARE_NATIVE = true;\n` +
    `window.EPICARE_DATA = ${safe(JSON.stringify(data))};\n` +
    `window.EPICARE_BRANCH2 = ${safe(JSON.stringify(branch2))};</script>\n` +
    `<script>${safe(js)}</script>`);

for (const left of ["styles.css", "app.js", "icons/icon-192.png"]) {
  if (html.includes(`"${left}"`)) throw new Error(`build-web: ${left} was not inlined (index.html changed?)`);
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, `// Generated by scripts/build-web.js from ../app. Do not edit.\nexport default ${JSON.stringify(html)};\n`);
console.log(`build-web: ${path.relative(process.cwd(), OUT)} (${Math.round(html.length / 1024)} KB, ` +
  `${data?.branches?.branch1?.patients?.length ?? 0} patients, branch 2 ${branch2 ? "included" : "absent"})`);
